 toggle(){this.enabled=!this.enabled;if(this.enabled){this.ensure();this.ctx?.resume().catch(()=>{});}$('audioButton').setAttribute('aria-pressed',String(this.enabled));$('audioButton').setAttribute('aria-label',this.enabled?'Disable sound':'Enable sound');$('soundLabel').textContent=this.enabled?'SOUND ON':'SOUND OFF';if(!this.enabled)this.stop();},
 resume(){if(this.enabled){this.ensure();this.ctx?.resume().catch(()=>{});}},stop(){this.dieselV8?.stop();if(recordedGain&&this.ctx)recordedGain.gain.setTargetAtTime(0,this.ctx.currentTime,.05);if(this.ctx){this.gain.gain.setTargetAtTime(0,this.ctx.currentTime,.05);this.rotorGain.gain.setTargetAtTime(0,this.ctx.currentTime,.05);this.tyreGain.gain.setTargetAtTime(0,this.ctx.currentTime,.05);}},
 update(){if(!this.ctx||!this.enabled||airCombat.ejection||state.mode!=='playing'||vehiclePowerFactor()===0){this.stop();return;}const t=this.ctx.currentTime,p=state.profile,throttle=keys.has('KeyW')||keys.has('ArrowUp');let frequency=(state.rpm||750)/30,level=throttle?.07:.035;if(p.electric||p.kind==='bike'&&!p.combustion){frequency=130+state.speed*10;level=.012;}if(p.kind==='heli'){frequency=45+motion.rotor*95;level=.055*motion.rotor;this.rotorOsc.frequency.setTargetAtTime(3+motion.rotor*15,t,.1);}this.osc.frequency.setTargetAtTime(frequency,t,.025);this.harmonic.frequency.setTargetAtTime(frequency*.5,t,.025);this.filter.frequency.setTargetAtTime(p.kind==='bike'&&!p.combustion?600:frequency*(throttle?6:3),t,.05);const recorded=recordedSource&&state.vehicleId===recordedVehicleId,ute=state.vehicleId==='ute';this.gain.gain.setTargetAtTime(recorded||ute?0:level*this.volume,t,.025);this.dieselV8.update(state.rpm,throttle?(keys.has('ShiftLeft')||keys.has('ShiftRight')||state.manualGear===0?.18:1):0,this.volume,ute&&!recorded);this.rotorGain.gain.setTargetAtTime(p.kind==='heli'?.013*this.volume*motion.rotor:0,t,.05);const squeal=p.kind==='car'&&state.grounded&&state.speed>5?clamp((state.slip||0)/5+(keys.has('Space')?.3:0),0,1):0;this.tyreGain.gain.setTargetAtTime(squeal*.12*this.volume,t,.04);}
